#!/usr/bin/env python3
"""Run the actual broadcast manager, paginated loader, service and UI against JVM fixtures.

Network, clock, SharedPreferences, Android widgets and service scheduling are controlled
fixtures; no APK is assembled, no device or live Telegram account is contacted.
"""
