SOURCES = [PROD / 'org/telegram/messenger' / name for name in (
    'MangoUserBroadcastManager.java', 'MangoBroadcastTargets.java', 'MangoUserBroadcastService.java')]
SOURCES.append(PROD / 'org/telegram/ui/MangoUserBroadcastActivity.java')
resource_source = '\n'.join(path.read_text() for path in SOURCES)
resource_groups = {}
for kind, key in sorted(set(re.findall(r'(?<!android\.)R\.(string|drawable)\.(\w+)', resource_source))):
    resource_groups.setdefault(kind, []).append(key)
FIXTURES['org/telegram/messenger/R.java'] = 'package org.telegram.messenger;public class R {' + ''.join(
    'public static class '+kind+' {'+''.join('public static final int '+key+'='+str(i)+';' for i,key in enumerate(keys, 1))+'}'
    for kind,keys in resource_groups.items())+'}'
with tempfile.TemporaryDirectory(prefix='mango-user-broadcast-') as folder:
    base = Path(folder)
    sources = list(SOURCES)
    for name, source in FIXTURES.items():
        file = base / name
        file.parent.mkdir(parents=True, exist_ok=True)
        file.write_text(source)
        sources.append(file)
    sources.append(ROOT / 'Tools/tests/UserBroadcastRegression.java')
    subprocess.run([str(JAVA / 'javac'), '-d', str(base / 'classes')] + list(map(str, sources)), check=True)
    subprocess.run([str(JAVA / 'java'), '-cp', str(base / 'classes'), 'org.telegram.messenger.UserBroadcastRegression'], check=True)
